-- Exact economic lineage and retained, explicitly local paper evidence.
-- Rational components use canonical reduced integer TEXT in typed JSON. The
-- validator bounds each component to 4096 digits before arithmetic allocation.
CREATE TABLE accounting_evidence(evidence_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(account_id),kind TEXT NOT NULL CHECK(kind IN ('initial','mark','fill','flow','correction','fx')),provenance TEXT NOT NULL CHECK(provenance='local-paper'),payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64),event_at_us INTEGER NOT NULL,received_at_us INTEGER NOT NULL,known_at_us INTEGER NOT NULL,recorded_at_us INTEGER NOT NULL,CHECK(event_at_us<=received_at_us AND received_at_us<=known_at_us)) STRICT;
CREATE TABLE accounting_operations(operation_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(account_id),evidence_id TEXT NOT NULL UNIQUE REFERENCES accounting_evidence(evidence_id),kind TEXT NOT NULL CHECK(kind IN ('initial','fill','flow','correction')),transaction_id TEXT NOT NULL UNIQUE REFERENCES journal_transactions(transaction_id),recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE accounting_state(account_id TEXT PRIMARY KEY REFERENCES accounts(account_id),units_json TEXT NOT NULL CHECK(json_valid(units_json)),high_water_json TEXT NOT NULL CHECK(json_valid(high_water_json)),day_open_json TEXT NOT NULL CHECK(json_valid(day_open_json)),day_start_us INTEGER,closed INTEGER NOT NULL CHECK(closed IN (0,1)),unresolved INTEGER NOT NULL CHECK(unresolved IN (0,1)),last_mark_id TEXT REFERENCES equity_marks(mark_id),rollover_pending INTEGER NOT NULL DEFAULT 0 CHECK(rollover_pending IN (0,1))) STRICT;
CREATE TABLE exact_marks(mark_id TEXT PRIMARY KEY REFERENCES equity_marks(mark_id),account_id TEXT NOT NULL REFERENCES accounts(account_id),evidence_id TEXT NOT NULL REFERENCES accounting_evidence(evidence_id),exact_json TEXT NOT NULL CHECK(json_valid(exact_json)),holdings_json TEXT NOT NULL CHECK(json_valid(holdings_json)),journal_sequence INTEGER NOT NULL CHECK(journal_sequence>=0),reconcile_id TEXT REFERENCES reconciliations(reconcile_id),ready INTEGER NOT NULL CHECK(ready IN (0,1)),recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE exact_flows(flow_id TEXT PRIMARY KEY REFERENCES external_flows(flow_id),account_id TEXT NOT NULL REFERENCES accounts(account_id),preflow_mark_id TEXT NOT NULL REFERENCES exact_marks(mark_id),units_delta_json TEXT NOT NULL CHECK(json_valid(units_delta_json)),units_after_json TEXT NOT NULL CHECK(json_valid(units_after_json)),closed INTEGER NOT NULL CHECK(closed IN (0,1)),recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE accounting_findings(finding_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(account_id),evidence_id TEXT NOT NULL REFERENCES accounting_evidence(evidence_id),reason TEXT NOT NULL,recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE accounting_rounding(rounding_id TEXT PRIMARY KEY,transaction_id TEXT NOT NULL REFERENCES journal_transactions(transaction_id),exact_residual_json TEXT NOT NULL CHECK(json_valid(exact_residual_json)),policy TEXT NOT NULL,recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TRIGGER accounting_evidence_no_update BEFORE UPDATE ON accounting_evidence BEGIN SELECT RAISE(ABORT,'append-only accounting_evidence'); END;
CREATE TRIGGER accounting_evidence_no_delete BEFORE DELETE ON accounting_evidence BEGIN SELECT RAISE(ABORT,'append-only accounting_evidence'); END;
CREATE TRIGGER accounting_operations_no_update BEFORE UPDATE ON accounting_operations BEGIN SELECT RAISE(ABORT,'append-only accounting_operations'); END;
CREATE TRIGGER accounting_operations_no_delete BEFORE DELETE ON accounting_operations BEGIN SELECT RAISE(ABORT,'append-only accounting_operations'); END;
CREATE TRIGGER exact_marks_no_update BEFORE UPDATE ON exact_marks BEGIN SELECT RAISE(ABORT,'append-only exact_marks'); END;
CREATE TRIGGER exact_marks_no_delete BEFORE DELETE ON exact_marks BEGIN SELECT RAISE(ABORT,'append-only exact_marks'); END;
CREATE TRIGGER exact_flows_no_update BEFORE UPDATE ON exact_flows BEGIN SELECT RAISE(ABORT,'append-only exact_flows'); END;
CREATE TRIGGER exact_flows_no_delete BEFORE DELETE ON exact_flows BEGIN SELECT RAISE(ABORT,'append-only exact_flows'); END;
CREATE TRIGGER accounting_findings_no_update BEFORE UPDATE ON accounting_findings BEGIN SELECT RAISE(ABORT,'append-only accounting_findings'); END;
CREATE TRIGGER accounting_findings_no_delete BEFORE DELETE ON accounting_findings BEGIN SELECT RAISE(ABORT,'append-only accounting_findings'); END;
CREATE TRIGGER accounting_rounding_no_update BEFORE UPDATE ON accounting_rounding BEGIN SELECT RAISE(ABORT,'append-only accounting_rounding'); END;
CREATE TRIGGER accounting_rounding_no_delete BEFORE DELETE ON accounting_rounding BEGIN SELECT RAISE(ABORT,'append-only accounting_rounding'); END;
